export const starter = "// @title My Game\nlet x = 76;\nlet y = 68;\nlet gx = 14;\nlet gy = 8;\nlet gems = 0;\n\nfunction draw() {\n  put(1, 1, 'GEMS ' + gems);\n  put(gx, gy, '💎', 4);\n}\n\ndraw();\n\nfunction tick() {\n  x = Math.max(0, Math.min(152, x + btn(3) - btn(2)));\n  y = Math.max(0, Math.min(136, y + btn(1) - btn(0)));\n\n  if (Math.abs(x - gx * 8) < 6 && Math.abs(y - gy * 8) < 6) {\n    put(gx, gy, ' ');\n    gems += 1;\n    gx = Math.floor(Math.random() * 20);\n    gy = 2 + Math.floor(Math.random() * 16);\n    draw();\n    play(0, 'T240O6N1cG');\n  }\n\n  spr(x, y, '👾', 6);\n}\n";

